-- Create "idempotency_keys" table
CREATE TABLE "idempotency_keys" ("id" character varying(40) NOT NULL, "credential" character varying(40) NOT NULL, "key" character varying(255) NOT NULL, "request_hash" bytea NOT NULL, "status" bigint NULL, "body" bytea NULL, "created_at" timestamptz NOT NULL, "tenant_id" character varying(40) NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "idempotency_keys_tenants_idempotency_keys" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "idempotency_keys_credential" CHECK ((credential)::text ~ '^(tok|usr)_[a-z2-7]{26}$'::text), CONSTRAINT "idempotency_keys_hash_len" CHECK (length(request_hash) = 32), CONSTRAINT "idempotency_keys_id_format" CHECK ((id)::text ~ '^idk_[a-z2-7]{26}$'::text), CONSTRAINT "idempotency_keys_key" CHECK ((key)::text ~ '^[ -~]{1,255}$'::text), CONSTRAINT "idempotency_keys_outcome" CHECK ((status IS NULL) = (body IS NULL)), CONSTRAINT "idempotency_keys_status" CHECK ((status IS NULL) OR ((status >= 200) AND (status <= 299)) OR ((status >= 400) AND (status <= 499))));
-- Create index "idempotencykey_created_at" to table: "idempotency_keys"
CREATE INDEX "idempotencykey_created_at" ON "idempotency_keys" ("created_at");
-- Create index "idempotencykey_tenant_id_credential_key" to table: "idempotency_keys"
CREATE UNIQUE INDEX "idempotencykey_tenant_id_credential_key" ON "idempotency_keys" ("tenant_id", "credential", "key");
